<template>
  <section class="knowledge-workspace">
    <div class="office-toolbar"><div><h1>知识库</h1><span class="office-muted">{{ total }} 篇 · 我的贡献 {{ items.filter(i=>String(i.contributorId)===userId).length }}</span></div><el-button @click="newCategory">新建分类</el-button><el-button type="primary" @click="edit()">新建知识</el-button></div>
    <div class="office-toolbar"><el-input v-model="query" placeholder="搜索标题、标签或正文" clearable/><el-select v-model="category" placeholder="全部分类" clearable><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="String(c.id)"/></el-select><el-checkbox v-model="onlyFavorites">收藏</el-checkbox><el-button @click="manageVisible=true">分类管理</el-button><el-button @click="showContributions">贡献统计</el-button></div>
    <el-dialog v-model="manageVisible" title="知识分类" width="min(520px,94vw)"><div v-for="c in categories" :key="c.id" class="office-toolbar"><span>{{ c.name }}</span><div class="office-actions" v-if="admin"><el-button circle title="重命名分类" @click="renameCategory(c)"><span class="material-symbols-outlined">edit</span></el-button><el-button circle title="删除分类" @click="removeCategory(c)"><span class="material-symbols-outlined">delete</span></el-button></div></div><el-empty v-if="!categories.length" description="暂无分类"/></el-dialog>
    <el-dialog v-model="contributionVisible" title="知识贡献统计" width="min(620px,94vw)"><el-table :data="contributions"><el-table-column prop="name" label="成员" min-width="120"/><el-table-column prop="articles" label="条目"/><el-table-column prop="views" label="浏览"/><el-table-column prop="favorites" label="收藏"/></el-table></el-dialog>
    <div v-loading="loading" class="knowledge-list">
      <article v-for="item in filtered" :key="item.knowledgeId"><button class="knowledge-title office-link" @click="open(item)">{{ item.title }}</button><p class="knowledge-summary">{{ item.content?.slice(0,160) }}</p><div class="office-toolbar"><span class="office-muted">{{ item.contributorName || '团队成员' }} · {{ categoryName(item.categoryId) }} · 浏览 {{ item.viewCount }}</span><el-tag v-for="tag in tags(item)" :key="tag" size="small">{{ tag }}</el-tag><el-button circle :title="favorites.includes(item.knowledgeId)?'取消收藏':'收藏'" @click="favorite(item)"><span class="material-symbols-outlined">{{ favorites.includes(item.knowledgeId)?'star':'star_border' }}</span></el-button><el-button v-if="canEdit(item)" circle title="编辑知识" @click="edit(item)"><span class="material-symbols-outlined">edit</span></el-button></div></article>
      <el-empty v-if="!filtered.length" description="还没有符合条件的知识"/>
    </div>
    <el-pagination v-if="total>50" layout="prev,pager,next" :total="total" :page-size="50" v-model:current-page="page" @current-change="load"/>
    <el-dialog v-model="editorVisible" :title="editingId?'编辑知识':'新建知识'" width="min(720px,94vw)"><form class="office-form" @submit.prevent="save"><label>标题<el-input v-model="form.title" maxlength="200" required/></label><label>分类<el-select v-model="form.categoryId" clearable><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="String(c.id)"/></el-select></label><label>标签<el-select v-model="form.tags" multiple filterable allow-create default-first-option :multiple-limit="20"/></label><label>正文<el-input v-model="form.content" type="textarea" :rows="12" maxlength="1000000" required/></label><div class="office-toolbar"><el-button v-if="editingId" type="danger" plain @click="remove">删除知识</el-button><el-button type="primary" native-type="submit" :loading="saving">发布</el-button></div></form></el-dialog>
    <el-dialog v-model="detailVisible" :title="detail?.title" width="min(800px,94vw)"><div class="office-muted">{{ detail?.contributorName }} · 浏览 {{ detail?.viewCount }}</div><div class="knowledge-content">{{ detail?.content }}</div><template #footer><el-button v-if="detail&&canEdit(detail)" @click="detailVisible=false;edit(detail)">编辑</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {useWorkspaceStore} from '@/stores/workspace'
const workspace=useWorkspaceStore(),items=ref<any[]>([]),categories=ref<any[]>([]),favorites=ref<string[]>([]),query=ref(''),category=ref(''),onlyFavorites=ref(false),page=ref(1),total=ref(0),loading=ref(false),saving=ref(false),editorVisible=ref(false),detailVisible=ref(false),detail=ref<any>(),editingId=ref(''),userId=ref(''),admin=ref(false)
const form=ref({title:'',content:'',categoryId:'',tags:[] as string[]})
const manageVisible=ref(false),contributionVisible=ref(false),contributions=ref<any[]>([])
async function showContributions(){try{const r:any=await request.get('/knowledge/contributions');contributions.value=r.data;contributionVisible.value=true}catch{}}
async function renameCategory(c:any){try{const r=await ElMessageBox.prompt('分类名称','重命名分类',{inputValue:c.name,inputValidator:v=>!!v?.trim()&&v.length<=100});await request.put('/knowledge/categories/'+c.id,{name:r.value});await load()}catch{}}
async function removeCategory(c:any){try{await ElMessageBox.confirm('移除分类后，原条目归入未分类。','删除分类');await request.delete('/knowledge/categories/'+c.id);if(category.value===String(c.id))category.value='';await load()}catch{}}
function tags(item:any):string[]{try{return JSON.parse(item.tagsJson||'[]')}catch{return []}}
const filtered=computed(()=>items.value.filter(i=>(!category.value||String(i.categoryId)===category.value)&&(!onlyFavorites.value||favorites.value.includes(i.knowledgeId))&&(!query.value||[i.title,i.content,...tags(i)].join(' ').toLowerCase().includes(query.value.toLowerCase()))))
function categoryName(id:any){return categories.value.find(c=>String(c.id)===String(id))?.name||'未分类'}
function canEdit(item:any){return admin.value||String(item.contributorId)===userId.value}
async function load(){loading.value=true;try{const r:any=await request.get('/knowledge/list',{params:{pageNum:page.value,pageSize:50}});items.value=r.data.records;total.value=Number(r.data.total);const c:any=await request.get('/knowledge/categories');categories.value=c.data;const f:any=await request.get('/knowledge/favorites');favorites.value=f.data}catch{}finally{loading.value=false}}
function edit(item?:any){editingId.value=item?.knowledgeId||'';form.value={title:item?.title||'',content:item?.content||'',categoryId:item?.categoryId?String(item.categoryId):'',tags:item?tags(item):[]};editorVisible.value=true}
async function open(item:any){try{const r:any=await request.get('/knowledge/'+item.knowledgeId);detail.value=r.data;detailVisible.value=true;item.viewCount=r.data.viewCount}catch{}}
async function save(){if(!form.value.title.trim()||!form.value.content.trim())return;saving.value=true;try{const body={title:form.value.title.trim(),content:form.value.content,categoryId:form.value.categoryId||null,tagsJson:JSON.stringify(form.value.tags)};if(editingId.value)await request.put('/knowledge/'+editingId.value,body);else await request.post('/knowledge/create',body);editorVisible.value=false;await load();ElMessage.success('知识已发布')}catch{}finally{saving.value=false}}
async function newCategory(){try{const r=await ElMessageBox.prompt('分类名称','新建分类',{inputValidator:v=>!!v?.trim()&&v.length<=100});await request.post('/knowledge/categories',{name:r.value});await load()}catch{}}
async function favorite(item:any){try{await request.put(`/knowledge/${item.knowledgeId}/favorite`,null,{params:{value:!favorites.value.includes(item.knowledgeId)}});await load()}catch{}}
async function remove(){try{await ElMessageBox.confirm('确认删除此知识条目？','删除知识',{type:'warning'});await request.delete('/knowledge/'+editingId.value);editorVisible.value=false;await load()}catch{}}
onMounted(async()=>{try{const u:any=await request.get('/user/info');userId.value=String(u.data.userId);const m:any=await request.get(`/space/${workspace.spaceId}/members`);admin.value=m.data.some((m:any)=>String(m.userId)===userId.value&&['1','ADMIN'].includes(String(m.roleType)));await load()}catch{}})
</script>
<style scoped>
.knowledge-workspace{min-width:0}.knowledge-workspace h1{margin:0 0 6px;font-size:var(--text-heading)}.knowledge-list article{padding:var(--space-5) 0;border-bottom:1px solid var(--c-border)}.knowledge-title{font-size:var(--text-section);font-weight:600;text-align:left}.knowledge-summary{color:var(--c-text-secondary);overflow-wrap:anywhere;line-height:1.6}.knowledge-content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;padding-block:var(--space-5)}.knowledge-workspace .office-toolbar{flex-wrap:wrap}.knowledge-workspace .el-input{max-width:360px}.knowledge-workspace .el-select{max-width:220px}.material-symbols-outlined{font-size:18px}
</style>
